<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('hunts.manage');$pdo=db();if(is_post()){verify_csrf();try{$a=(string)input('action');if($a==='create'){$pdo->prepare('INSERT INTO question_collections(collection_name,spot_id,description,rotation_method,questions_per_session,status,created_by) VALUES(?,?,?,?,?,?,?)')->execute([trim((string)input('collection_name')),trim((string)input('spot_id')),trim((string)input('description'))?:null,strtoupper((string)input('rotation_method')),max(1,(int)input('questions_per_session',1)),strtoupper((string)input('status','ACTIVE')),admin()['id']]);}elseif($a==='add'){$collectionId=(int)input('collection_id');$questionId=(int)input('riddle_id');$next=$pdo->prepare('SELECT COALESCE(MAX(question_order),0)+1 FROM question_collection_items WHERE collection_id=?');$next->execute([$collectionId]);$order=(int)$next->fetchColumn();$pdo->prepare('INSERT IGNORE INTO question_collection_items(collection_id,riddle_id,question_order) VALUES(?,?,?)')->execute([$collectionId,$questionId,$order]);}elseif($a==='remove'){$pdo->prepare('DELETE FROM question_collection_items WHERE collection_id=? AND riddle_id=?')->execute([(int)input('collection_id'),(int)input('riddle_id')]);}flash('success','Collection updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/hunts/collections.php');}$spots=$pdo->query('SELECT spot_id,spot_name FROM spot_campaigns ORDER BY spot_name')->fetchAll();try{$questions=$pdo->query('SELECT riddle_id,spot_id,riddle_text FROM riddle_pool WHERE status="ACTIVE" ORDER BY riddle_id DESC')->fetchAll();}catch(Throwable $e){$questions=$pdo->query('SELECT riddle_id,spot_id,riddle_text FROM riddle_pool ORDER BY riddle_id DESC')->fetchAll();}$collections=$pdo->query('SELECT c.*,s.spot_name,(SELECT COUNT(*) FROM question_collection_items i WHERE i.collection_id=c.collection_id) question_count FROM question_collections c JOIN spot_campaigns s ON s.spot_id=c.spot_id ORDER BY c.collection_id DESC')->fetchAll();$pageTitle='Question Collections';$pageSubtitle='Organize questions with configurable rotation';require APP_ROOT.'/includes/header.php';?><section class="panel"><h2>Create collection</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="field"><label>Collection name</label><input name="collection_name" required></div><div class="field"><label>Master category campaign</label><select name="spot_id" required><?php foreach($spots as $s):?><option value="<?=e($s['spot_id'])?>"><?=e($s['spot_name'])?></option><?php endforeach?></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Rotation method</label><select name="rotation_method"><option>SEQUENTIAL</option><option>RANDOM</option><option>RANDOM_NO_REPEAT</option><option>ROUND_ROBIN</option><option>WEIGHTED</option></select></div><div class="field"><label>Questions per session</label><input type="number" name="questions_per_session" min="1" value="1"></div><div class="field"><label>Status</label><select name="status"><option>ACTIVE</option><option>INACTIVE</option></select></div><div class="field full"><button class="btn">Create collection</button></div></form></section><section class="panel"><h2>Collections</h2><?php foreach($collections as $c):?><article class="card" style="margin-bottom:12px"><div class="panel-head"><div><strong><?=e($c['collection_name'])?></strong><br><small><?=e($c['spot_name'])?> · <?=e($c['rotation_method'])?> · <?=e($c['question_count'])?> questions</small></div><span class="badge <?=strtolower(e($c['status']))?>"><?=e($c['status'])?></span></div><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="collection_id" value="<?=e($c['collection_id'])?>"><select name="riddle_id" required><?php foreach($questions as $q): if($q['spot_id']===$c['spot_id']):?><option value="<?=e($q['riddle_id'])?>"><?=e(mb_strimwidth($q['riddle_text'],0,70,'…'))?></option><?php endif;endforeach?></select><button class="btn small">Add question</button></form></article><?php endforeach?></section><?php require APP_ROOT.'/includes/footer.php';
